6	/// Entry point for the shared UI: connection flow → robot control, with one live
7	/// viewport placed according to how much room there is.
8	///
9	/// The tab bar lives here rather than in the app target because the Live tab and
10	/// the Robot tab share a `RobotSession` and a `ViewportModel`, and because
11	/// whether Live exists at all depends on the size class — which an `App` cannot
12	/// read. The app target's own developer screen is injected and handed to
13	/// Settings, so it keeps owning that screen without a tab or a nested tab bar.
14	public struct ReachyRootView<Developer: View>: View {
15	    private enum TabID: Hashable {
16	        case robot
17	        case live
18	        case apps
19	    }
20	
21	    @State private var session: RobotSession
22	    @State private var viewport: ViewportModel
23	    /// One Hugging Face session for the whole app, restored from the Keychain on
24	    /// launch and handed down through the environment — the account outlives any
25	    /// one robot connection, and several screens read it.
26	    @State private var hfAccount: HFAccount
27	    @State private var tab: TabID = .robot
28	    @State private var showsSettings = false
29	    /// The two ways to reach a robot are two entry points to the same list, so it
30	    /// is presented from here rather than owned by either screen that offers it.
31	    @State private var showsRemoteRobots = false
32	    /// Held for as long as the remote session is: dropping it would close the
33	    /// peer connection the session is talking over.
34	    @State private var remoteLink: RemoteRobotLink?
35	    @Environment(\.scenePhase) private var scenePhase
36	    @Environment(\.reachyPreviewMode) private var previewMode
37	
38	    #if os(macOS)
39	        /// `horizontalSizeClass` does not exist on macOS, where a window is always
40	        /// wide enough for the two-column layout.
41	        private var isCompact: Bool {
42	            false
43	        }
44	    #else
45	        @Environment(\.horizontalSizeClass) private var horizontalSizeClass
46	        private var isCompact: Bool {
47	            horizontalSizeClass == .compact
48	        }
49	    #endif
50	
51	    private let developer: Developer
52	
53	    @MainActor
54	    public init(@ViewBuilder developer: () -> Developer) {
55	        self.init(session: RobotSession(), developer: developer)
56	    }
57	
58	    /// Internal so previews can park the root in a phase a real connection would have to reach.
59	    @MainActor
60	    init(
61	        session: RobotSession,
62	        viewport: ViewportModel = ViewportModel(),
63	        hfAccount: HFAccount? = nil,
64	        @ViewBuilder developer: () -> Developer
65	    ) {
66	        _session = State(initialValue: session)
67	        _viewport = State(initialValue: viewport)
68	        _hfAccount = State(
69	            initialValue: hfAccount ?? HFAccount(store: KeychainHFTokenStore())
70	        )
71	        self.developer = developer()
72	    }
73	
74	    public var body: some View {
75	        TabView(selection: $tab) {
76	            Tab("Robot", systemImage: "figure.wave", value: TabID.robot) {
77	                robotTab
78	            }
79	            if offersLiveTab {
80	                Tab("Live", systemImage: "cube.transparent", value: TabID.live) {
81	                    liveTab
82	                }
83	            }
84	            Tab("Apps", systemImage: "square.grid.2x2", value: TabID.apps) {
85	                appsTab
86	            }
87	        }
88	        .environment(\.reachyDeveloperScreen) { [developer] in AnyView(developer) }
89	        .environment(hfAccount)
90	        .sheet(isPresented: $showsRemoteRobots) {
91	            NavigationStack {
92	                YourReachiesScreen(
93	                    model: YourReachiesModel(
94	                        listing: CentralRelayClient { [hfAccount] in await hfAccount.currentToken() },
95	                        // `.needsReauth` also carries a username, so the state is
96	                        // the question, not whether a name is known.
97	                        isSignedIn: { [hfAccount] in
98	                            if case .signedIn = hfAccount.state {
99	                                true
100	                            } else {
101	                                false
102	                            }
103	                        }
104	                    ),
105	                    connect: connectRemotely,
106	                    // Pushed inside this sheet rather than sending the user to
107	                    // the robot's Settings: that screen is presented from the
108	                    // Live tab, which does not exist until a robot is connected —
109	                    // exactly the case that brings anyone here.
110	                    signIn: { HFSignInScreen(session: session, model: HFSignInModel(account: hfAccount)) }
111	                )
112	            }
113	        }
114	        .task {
115	            guard !previewMode else { return }
116	            hfAccount.restore()
117	        }
118	        .task(id: viewportAddress) {
119	            guard !previewMode else { return }
120	            if let viewportAddress {
121	                viewport.attach(to: viewportAddress)
122	            } else {
123	                viewport.detach()
124	            }
125	        }
126	        .onChange(of: viewportIsOnScreen, initial: true) { _, onScreen in
127	            guard !previewMode else { return }
128	            viewport.setActive(onScreen)
129	        }
130	        .onChange(of: offersLiveTab) { _, offered in
131	            // The tab it points at is about to stop existing; SwiftUI would pick
132	            // a replacement of its own, which lands on Diagnostics.
133	            if !offered, tab == .live {
134	                tab = .robot
135	            }
136	        }
137	    }
138	
139	    /// Opens the relay session first, then hands the session a client that speaks
140	    /// over it. `start()` only begins asking central for a session — nothing has
141	    /// reached the robot yet, and the control channel's own deadline is what
142	    /// bounds the wait if it never answers.
143	    private func connectRemotely(to robot: CentralRobot) {
144	        showsRemoteRobots = false
145	        remoteLink?.stop()
146	        let link = RemoteRobotLink(
147	            robot: robot,
148	            relay: CentralRelayClient { [hfAccount] in await hfAccount.currentToken() }
149	        )
150	        remoteLink = link
151	        link.start()
152	        tab = .robot
153	        Task { await session.connect(using: link.client) }
154	    }
155	
156	    // MARK: - Tabs
157	
158	    @ViewBuilder
159	    private var robotTab: some View {
160	        switch session.phase {
161	        case .idle, .connecting:
162	            ConnectionScreen(session: session, showRemoteRobots: { showsRemoteRobots = true })
163	        case .connected, .unreachable:
164	            if isCompact {
165	                NavigationStack { RobotScreen(session: session) }
166	            } else {
167	                HStack(spacing: 0) {
168	                    wideViewport
169	                    Divider()
170	                    NavigationStack {
171	                        RobotScreen(session: session)
172	                            .columnTitleStyle()
173	                    }
174	                    .frame(minWidth: 320, idealWidth: 380, maxWidth: 420)
175	                }
176	            }
177	        }
178	    }
179	
180	    /// The store is its own destination rather than a row inside the robot screen:
181	    /// it is somewhere a user goes back to, and a widget can open it directly.
182	    private var appsTab: some View {
183	        NavigationStack {
184	            if session.canManageApps {
185	                AppStoreScreen(session: session)
186	            } else {
187	                // The catalogue is served by the daemon, not by the Hub — the robot
188	                // fetches it — so there is genuinely nothing to show without one.
189	                // Both ways to get one are offered, because "not on this network"
190	                // stopped meaning "out of reach".
191	                ContentUnavailableView {
192	                    Label("No robot connected", systemImage: "square.grid.2x2")
193	                } description: {
194	                    Text("Apps are installed on the robot, so this needs one connected.")
195	                } actions: {
196	                    Button("Find one nearby") { tab = .robot }
197	                    Button("Your Reachies") { showsRemoteRobots = true }
198	                }
199	                .navigationTitle("Apps")
200	            }
201	        }
202	    }
203	
204	    @ViewBuilder
205	    private var wideViewport: some View {
206	        if viewportAddress == nil {
207	            ContentUnavailableView(
208	                "No live view",
209	                systemImage: "cube.transparent",
210	                description: Text("Start the robot backend to see the model and the camera.")
211	            )
212	            .frame(maxWidth: .infinity, maxHeight: .infinity)
213	        } else if session.isAwake {
214	            ViewportView(model: viewport, offersCamera: session.hasCamera)
215	        } else {
216	            asleepViewport
217	        }
218	    }
219	
220	    private var liveTab: some View {
221	        NavigationStack {
222	            // No `ignoresSafeArea` here: the camera hangs its joystick off a
223	            // bottom safe-area inset, which would then be laid out under the tab
224	            // bar and clipped.
225	            liveContent
226	                .navigationTitle("Live")
227	                .darkTitleBar()
228	                .toolbar {
229	                    ToolbarItem {
230	                        Button {
231	                            showsSettings = true
232	                        } label: {
233	                            Label("Settings", systemImage: "gearshape")
234	                        }
235	                    }
236	                }
237	                .sheet(isPresented: $showsSettings) {
238	                    NavigationStack {
239	                        SettingsScreen(session: session)
240	                            .toolbar {
