            }
            if offersLiveTab {
                Tab("Live", systemImage: "cube.transparent", value: TabID.live) {
                    liveTab
                }
            }
            Tab("Apps", systemImage: "square.grid.2x2", value: TabID.apps) {
                appsTab
            }
        }
        .environment(\.reachyDeveloperScreen) { [developer] in AnyView(developer) }
        .environment(hfAccount)
        .sheet(isPresented: $showsRemoteRobots) {
            NavigationStack {
                YourReachiesScreen(
                    model: YourReachiesModel(
                        listing: CentralRelayClient { [hfAccount] in await hfAccount.currentToken() },
                        // `.needsReauth` also carries a username, so the state is
                        // the question, not whether a name is known.
                        isSignedIn: { [hfAccount] in
                            if case .signedIn = hfAccount.state {
                                true
                            } else {
                                false
                            }
                        }
                    ),
                    connect: connectRemotely,
                    // Pushed inside this sheet rather than sending the user to
                    // the robot's Settings: that screen is presented from the
                    // Live tab, which does not exist until a robot is connected —
                    // exactly the case that brings anyone here.
                    signIn: { HFSignInScreen(session: session, model: HFSignInModel(account: hfAccount)) }
                )
            }
        }
        .task {
            guard !previewMode else { return }
            hfAccount.restore()
        }
        .task(id: viewportAddress) {
            guard !previewMode else { return }
            if let viewportAddress {
                viewport.attach(to: viewportAddress)
            } else {
                viewport.detach()
            }
        }
        .onChange(of: viewportIsOnScreen, initial: true) { _, onScreen in
            guard !previewMode else { return }
            viewport.setActive(onScreen)
        }
        .onChange(of: offersLiveTab) { _, offered in
            // The tab it points at is about to stop existing; SwiftUI would pick
            // a replacement of its own, which lands on Diagnostics.
            if !offered, tab == .live {
                tab = .robot
            }
        }
    }

    /// Opens the relay session first, then hands the session a client that speaks
    /// over it. `start()` only begins asking central for a session — nothing has
    /// reached the robot yet, and the control channel's own deadline is what
    /// bounds the wait if it never answers.
    private func connectRemotely(to robot: CentralRobot) {
        showsRemoteRobots = false
        remoteLink?.stop()
        let link = RemoteRobotLink(
            robot: robot,
            relay: CentralRelayClient { [hfAccount] in await hfAccount.currentToken() }
        )
        remoteLink = link
        link.start()
        tab = .robot
        Task { await session.connect(using: link.client) }
    }

    // MARK: - Tabs

    @ViewBuilder
    private var robotTab: some View {
        switch session.phase {
        case .idle, .connecting:
            ConnectionScreen(session: session, showRemoteRobots: { showsRemoteRobots = true })
        case .connected, .unreachable:
            if isCompact {
                NavigationStack { RobotScreen(session: session) }
            } else {
                HStack(spacing: 0) {
                    wideViewport
                    Divider()
                    NavigationStack {
                        RobotScreen(session: session)
                            .columnTitleStyle()
                    }
                    .frame(minWidth: 320, idealWidth: 380, maxWidth: 420)
                }
            }
        }
    }

    /// The store is its own destination rather than a row inside the robot screen:
    /// it is somewhere a user goes back to, and a widget can open it directly.
    private var appsTab: some View {
        NavigationStack {
            if session.canManageApps {
                AppStoreScreen(session: session)
            } else {
                // The catalogue is served by the daemon, not by the Hub — the robot
                // fetches it — so there is genuinely nothing to show without one.
                // Both ways to get one are offered, because "not on this network"
                // stopped meaning "out of reach".
                ContentUnavailableView {
                    Label("No robot connected", systemImage: "square.grid.2x2")
                } description: {
                    Text("Apps are installed on the robot, so this needs one connected.")
                } actions: {
                    Button("Find one nearby") { tab = .robot }
                    Button("Your Reachies") { showsRemoteRobots = true }
                }
                .navigationTitle("Apps")
            }
        }
    }

    @ViewBuilder
    private var wideViewport: some View {
        if viewportAddress == nil {
            ContentUnavailableView(
                "No live view",
                systemImage: "cube.transparent",
                description: Text("Start the robot backend to see the model and the camera.")
            )
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if session.isAwake {
            ViewportView(model: viewport, offersCamera: session.hasCamera)
        } else {
            asleepViewport
        }
    }

    private var liveTab: some View {
        NavigationStack {
            // No `ignoresSafeArea` here: the camera hangs its joystick off a
            // bottom safe-area inset, which would then be laid out under the tab
            // bar and clipped.
            liveContent
                .navigationTitle("Live")
                .darkTitleBar()
                .toolbar {
                    ToolbarItem {
                        Button {
                            showsSettings = true
                        } label: {
                            Label("Settings", systemImage: "gearshape")
                        }
                    }
                }
                .sheet(isPresented: $showsSettings) {
                    NavigationStack {
                        SettingsScreen(session: session)
                            .toolbar {
                                ToolbarItem(placement: .cancellationAction) {
                                    Button("Done") { showsSettings = false }
                                }
                            }
                    }
                    .presentationDetents([.medium, .large])
                }
        }
    }

    /// Both streams would keep working while the robot sleeps — the camera hangs off
    /// `get_daemon` and the state stream off a running backend — but working is not the
    /// same as worth having. A motionless pose and a still frame cost the robot's radio
    /// and this phone's battery to show nothing, and a switcher between two inert views
    /// is a control that leads nowhere. So the tab keeps its place and offers the one
    /// thing that changes the situation.
    @ViewBuilder
    private var liveContent: some View {
        if session.isAwake {
            // Upwards only: the title bar above is pinned dark to match the black, while
            // the tab bar below is glass and has to keep materialising what every other
            // tab puts under it.
            ViewportView(model: viewport, offersCamera: session.hasCamera, backdropEdges: [.top, .horizontal])
        } else {
            asleepViewport
        }
    }

    private var asleepViewport: some View {
        AsleepBanner(session: session)
            .padding()
            .frame(maxWidth: 420)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
    }

    // MARK: - Placement

    /// Only on iPhone: where there is room, the viewport sits beside the controls
    /// instead of behind a tab.
    private var offersLiveTab: Bool {
        isCompact && viewportAddress != nil
    }

    /// Both the geometry and the state routes sit behind the backend, so an
    /// address alone is not enough to show anything.
    private var viewportAddress: RobotAddress? {
        session.isBackendRunning ? session.address : nil
    }

    /// The single lever for battery: nothing streams unless the viewport is the
    /// thing the user is actually looking at — and a sleeping robot is never that,
    /// however visible the tab is.
    private var viewportIsOnScreen: Bool {
        guard scenePhase == .active, viewportAddress != nil, session.isAwake else { return false }
        return isCompact ? tab == .live : tab == .robot
    }
}

private extension View {
    /// A large title inside a narrow side column is laid out against the window
    /// rather than the column, so it starts flush against the divider with no
    /// leading inset. Inline titles sit correctly.
    func columnTitleStyle() -> some View {
        #if os(iOS)
            navigationBarTitleDisplayMode(.inline)
        #else
            self
        #endif
    }

    /// The bar cannot take a background over the viewport — both
    /// `toolbarBackground(.visible:)` and its replacement `toolbarBackgroundVisibility`
    /// are ignored there — so its palette is pinned instead. Safe only because the content
    /// under it is pinned to match: on its own this put a white title on the 3D model's
    /// white backdrop.
    func darkTitleBar() -> some View {
        #if os(iOS)
            toolbarColorScheme(.dark, for: .navigationBar)
        #else
            self
        #endif
    }
}

import Foundation
@testable import ReachyKit
import Testing

/// A data channel that answers whatever a test scripts, and records what it was
/// asked. Stands in for the reliable `"data"` channel the robot opens.
///
/// Locks by hand rather than through `withLock`. A closure nested inside the
/// `AsyncStream` builder, capturing the escaping continuation, hands the
/// compiler's `ClosureLifetimeFixup` SIL pass a `convert_escape_to_noescape` it
/// never finishes walking: the whole test module compiles forever, so no test
/// in it ever runs and the failure reads as a hang in the code under test.
private final class FakeDataChannel: RemoteDataChannel, @unchecked Sendable {
    private let lock = NSLock()
    private var continuation: AsyncStream<String>.Continuation?
    private var pending: [String] = []
    private var recorded: [String] = []
    /// Answers keyed by the command that provokes them.
    private let scripted: [String: String]

    init(replies: [String: String] = [:]) {
        scripted = replies
    }

    var sent: [String] {
        lock.lock()
        defer { lock.unlock() }
        return recorded
    }

    func send(_ text: String) async throws {
        guard let reply = record(text) else { return }
        emit(reply)
    }

    /// Synchronous on purpose: `NSLock` is `noasync`, because a lock held across
    /// a suspension is a deadlock waiting for the right scheduling.
    private func record(_ text: String) -> String? {
        let command = try? JSONDecoder().decode(TypeOnly.self, from: Data(text.utf8)).type
        lock.lock()
        defer { lock.unlock() }
        recorded.append(text)
        guard let command else { return nil }
        return scripted[command]
    }

    func messages() -> AsyncStream<String> {
        AsyncStream { continuation in
            lock.lock()
            self.continuation = continuation
            let backlog = pending
            pending = []
            lock.unlock()
            for text in backlog {
                continuation.yield(text)
            }
        }
    }

    /// Anything the robot says on its own — a broadcast, or a reply to something
    /// this test never sent.
    ///
    /// Buffered until someone is listening: a real channel is subscribed to before
    /// anything is sent, while here `send` can answer before the reader's task has
    /// had a chance to run, and a dropped reply would look exactly like a robot
    /// that went quiet.
    func emit(_ text: String) {
        lock.lock()
        let listener = continuation
        if listener == nil {
            pending.append(text)
        }
        lock.unlock()
        listener?.yield(text)
    }

    private struct TypeOnly: Decodable {
        let type: String
    }
}

@Suite("Remote control channel", .timeLimit(.minutes(1)))
struct RemoteControlChannelTests {
    private func channel(
        _ replies: [String: String] = [:],
        timeout: Duration = .seconds(5)
    ) -> (RemoteControlChannel, FakeDataChannel) {
        let fake = FakeDataChannel(replies: replies)
        return (RemoteControlChannel(channel: fake, timeout: timeout), fake)
    }

    /// The robot answers by echoing the command back. There is no request id on
    /// this channel — the echoed `command` is the whole of the correlation.
    @Test("a command is matched to its reply by the command it echoes")
    func matchesByEchoedCommand() async throws {
        let (control, fake) = channel([
            "wake_up": #"{"status":"ok","command":"wake_up","completed":true}"#,
        ])

        try await control.perform("wake_up")

        let sent = try #require(fake.sent.first)
        #expect(sent.contains("\"type\":\"wake_up\"") || sent.contains("\"type\" : \"wake_up\""))
    }

    /// A failure comes back on the same channel, as a field rather than a status
    /// code, and carries the robot's own words.
    @Test("an error reply is thrown with the robot's own message")
    func throwsTheRobotsError() async {
        let (control, _) = channel([
            "wake_up": #"{"error":"Backend not running","command":"wake_up"}"#,
        ])

        await #expect(throws: RemoteControlChannel.Failure.robot("Backend not running")) {
            try await control.perform("wake_up")
        }
    }

    /// The robot broadcasts things nobody asked for — move progress, for one — and
    /// a reply to a command still in flight must not be lost among them.
    @Test("an unsolicited message does not satisfy a pending command")
    func ignoresUnrelatedMessages() async throws {
        let (control, fake) = channel()

        async let reply = control.perform("wake_up")
        try await Task.sleep(for: .milliseconds(50))
        fake.emit(#"{"type":"play_uploaded_move","upload_id":"u1","finished":true}"#)
        fake.emit(#"{"status":"ok","command":"goto_sleep","completed":true}"#)
        fake.emit(#"{"status":"ok","command":"wake_up","completed":true}"#)

        _ = try await reply
    }

    /// Nothing on this channel says how long a command may take, and a caller left
    /// awaiting forever is worse than one told the robot went quiet.
    @Test("a command the robot never answers gives up")
    func timesOut() async {
        let (control, _) = channel(timeout: .milliseconds(100))

        await #expect(throws: RemoteControlChannel.Failure.timedOut) {
            try await control.perform("wake_up")
        }
    }

    /// Not every reply echoes a command: `get_version` answers a bare
    /// `{"version": …}`, `get_hardware_id` a bare `{"hardware_id": …}`. The caller
    /// says which key identifies its reply, because nothing on the wire does.
    @Test("a reply that echoes no command is matched by the key it carries")
    func matchesByReplyKey() async throws {
        let (control, _) = channel(["get_version": #"{"version":"1.9.0"}"#])

        struct Reply: Decodable {
            let version: String
        }

        let reply = try await control.perform(
            "get_version",
            correlation: .replyKey("version"),
            expecting: Reply.self
        )

        #expect(reply.version == "1.9.0")
    }

    /// Telemetry always names a `type` and never a `command`. One of those
    /// broadcasts carries a `state` of its own, so a caller waiting on `get_state`
    /// must not take the first message that happens to hold the key.
    @Test("a broadcast is not mistaken for the keyed reply it resembles")
    func ignoresABroadcastCarryingTheSameKey() async throws {
        let (control, fake) = channel()

        async let reply = control.perform("get_state", correlation: .replyKey("state"))
        try await Task.sleep(for: .milliseconds(50))
        fake.emit(#"{"type":"daemon_status","robot_name":"reachy","state":"running"}"#)
        fake.emit(#"{"state":{"body_yaw":0.5}}"#)

        let data = try await reply
        let decoded = try JSONSerialization.jsonObject(with: data) as? [String: Any]
        #expect(decoded?["type"] == nil)
    }

    @Test("a reply with a payload comes back decoded")
    func decodesAPayload() async throws {
        let (control, _) = channel([
            "get_state": #"""
            {"command":"get_state","state":{"body_yaw":0.5,"motor_mode":"enabled","is_move_running":false}}
            """#,
        ])

        struct State: Decodable, Equatable {
            let bodyYaw: Double
            let motorMode: String

            enum CodingKeys: String, CodingKey {
                case bodyYaw = "body_yaw"
                case motorMode = "motor_mode"
            }
        }
        struct Reply: Decodable {
            let state: State
        }

        let reply = try await control.perform("get_state", expecting: Reply.self)

        #expect(reply.state == State(bodyYaw: 0.5, motorMode: "enabled"))
    }

    /// Two commands of the same name cannot be told apart on the wire, so they are
    /// not allowed to be in flight together — the second would take the first's
    /// reply.
    @Test("the same command twice runs one after the other")
    func serialisesIdenticalCommands() async throws {
        let (control, fake) = channel([
            "wake_up": #"{"status":"ok","command":"wake_up","completed":true}"#,
        ])

        async let first = control.perform("wake_up")
        async let second = control.perform("wake_up")
        _ = try await first
        _ = try await second

        #expect(fake.sent.count == 2)
    }

    /// Commands carry parameters, and the robot's models name them its way.
    @Test("a payload is sent alongside the command type")
    func sendsAPayload() async throws {
        let (control, fake) = channel([
            "set_volume": #"{"status":"ok","command":"set_volume","completed":true}"#,
        ])

        try await control.perform("set_volume", payload: ["volume": .number(42)])

        let sent = try #require(fake.sent.first)
        let object = try JSONSerialization.jsonObject(with: Data(sent.utf8)) as? [String: Any]
        #expect(object?["type"] as? String == "set_volume")
        #expect(object?["volume"] as? Double == 42)
    }
}

