    /// suspension is a deadlock waiting for the right scheduling.
    private func current() -> RTCDataChannel? {
        lock.lock()
        defer { lock.unlock() }
        return channel
    }

    private func enqueue(_ continuation: CheckedContinuation<RTCDataChannel, Never>) {
        lock.lock()
