/// DTLS are through — so the first command waits for a session as well as for a
/// reply, and gets its own budget for it. Both budgets are exercised here; only
/// the opening one can produce this failure in time.
@Test("the first command waits on the opening budget, not the reply budget")
func spendsTheOpeningBudgetFirst() async {
    let (control, _) = channel(timeout: .seconds(60), openingTimeout: .milliseconds(100))

    await #expect(throws: RemoteControlChannel.Failure.timedOut) {
